import sys

s = sys.stdin.read().split()[0]
if s[0] == '-' or '.' in s:
    print('Error')
else:
    h = int(s)
    total = 0
    for hour in range(1, h + 1):
        if hour <= 2:
            total += 100
        elif hour <= 5:
            total += 50
        else:
            total += 20
    print(total)

