    for _ in range(12):
        tests.append(str(rng.randint(0, 30)))
    for _ in range(4):
        tests.append(str(rng.randint(100, 1000000)))
    for _ in range(4):
        tests.append('-' + str(rng.randint(1, 1000)))
    for _ in range(4):
        tests.append(f"{rng.randint(0, 50)}.{rng.randint(1, 99)}")
    return tests

